#include <limits>
inline std::string construct_profile(int profile,int variant){
 using namespace opensim::services;int random=0,clocks=0,roots=0;std::string events;
 auto id=[](int n){std::ostringstream s;s<<"00000000-0000-0000-0000-"<<std::hex<<std::setw(12)<<std::setfill('0')<<n;return framework::Uuid(s.str());};
 UserAccount account(id(7));account.first_name="First";account.last_name="Last";
 framework::AgentCircuitData circuit;circuit.circuit_code=0xffffffffu;circuit.session_id=id(8);circuit.secure_session_id=id(9);circuit.caps_path=profile==22?LoginResponse::Text{}:LoginResponse::Text("caps/path/");
 GridUserInfo user;user.home_position={1.25f,-0.f,30};user.home_look_at={0,1,-2};GridRegion destination;destination.x=-256;destination.y=51200;destination.size_x=512;destination.size_y=1024;destination.set_server_uri("http://destination:9000/base/");GridRegion home;home.x=1024;home.y=-512;
 auto folder=[&](int n,std::optional<std::string> name){auto f=std::make_shared<LoginInventoryFolder>();f->id=id(n);f->name=name;f->version=65535;f->type=-1;return f;};auto root=folder(1,"My Inventory"),other=folder(2,"Other");other->parent=root->id;
 auto item=std::make_shared<InventoryItem>();item->id=id(4);item->asset_id=id(5);
 auto buddy=[&](std::optional<std::string> name,int mine,int theirs){auto b=std::make_shared<LoginFriendInfo>();b->friend_id=name;b->my_flags=mine;b->their_flags=theirs;return b;};
 LoginResponseInput input;input.account=&account;input.circuit=&circuit;input.grid_user=&user;input.destination=&destination;input.home=&home;input.skeleton=LoginResponseLibrary::Folders{root,other};input.gestures=std::vector<std::shared_ptr<InventoryItem>>{item};input.friends=std::vector<std::shared_ptr<LoginFriendInfo>>{buddy(id(3).str(),1,2),buddy(id(3).str(),3,4),buddy("bad",5,6),buddy(id(6).str()+";http://home/;First Last",INT32_MAX,INT32_MIN),buddy(id(5).str(),9,-1),buddy(std::nullopt,1,2)};
 input.where="safe";input.start_location="unused";input.position={99,99,99};input.look_at={1.25f,2,-0.f};input.message="Welcome";input.map_url="map";input.profile_url="profile";input.openid_url="openid";input.search_url="search";input.currency="currency";input.dst_zone="none";input.destinations_url="destinations";input.avatars_url="avatars";input.classified_fee="7";input.max_agent_groups=-9;input.real_id=id(6);
 input.library=std::make_shared<LoginResponseLibrary>();input.library->root=[&]()->std::shared_ptr<LoginInventoryFolder>{++roots;events+="root"+std::to_string(roots)+";";if((profile==9&&roots==1)||(profile==10&&roots==2))throw std::runtime_error("library root");if((profile==5&&roots==1)||(profile==6&&roots==2))return {};return root;};input.library->folders=[&]()->std::optional<LoginResponseLibrary::Folders>{events+="folders;";if(profile==11)throw std::runtime_error("folders");if(profile==7)return {};return LoginResponseLibrary::Folders{root,profile==8?nullptr:other};};
 LoginResponseEnvironment env;env.external_endpoint=[&](const GridRegion&)->std::optional<RegionEndpoint>{events+="endpoint;";if(profile==19)throw std::runtime_error("endpoint");if(profile==36)destination.x=-512;if(profile==18)return {};return RegionEndpoint{variant&1?"::1":"203.0.113.5",9000};};env.server_uri=[&](const GridRegion&)->std::optional<std::string>{events+="uri;";if(profile==20)throw std::runtime_error("uri");if(profile==37)destination.size_x=999;if(profile==21)return {};return "http://destination:9000/base/";};env.local_daylight=[&]{events+="local;";if(profile==34)throw std::runtime_error("local");return (variant&1)==0;};env.find_timezone=[&](const std::string& name)->LoginResponseEnvironment::Daylight{events+="find:"+name+";";if(name=="null-zone")return {};if(name!="summer"&&name!="winter"&&name!="throw-dst")throw std::runtime_error("zone");return [&,name]{events+="dst:"+name+";";if(name=="throw-dst")throw std::runtime_error("daylight");return name=="summer";};};
 switch(profile){case 1:input.skeleton.reset();break;case 2:input.skeleton->push_back(nullptr);break;case 3:input.gestures.reset();break;case 4:input.gestures->push_back(nullptr);break;case 12:input.friends.reset();break;case 13:input.friends->push_back(nullptr);break;case 14:input.account=nullptr;break;case 15:input.circuit=nullptr;break;case 16:input.grid_user=nullptr;break;case 17:input.destination=nullptr;break;case 24:input.home=nullptr;break;case 25:user.home_position={std::numeric_limits<float>::quiet_NaN(),std::numeric_limits<float>::infinity(),1e-10f};user.home_look_at={-std::numeric_limits<float>::infinity(),1e20f,-0.f};input.look_at=user.home_position;break;case 26:case 34:input.dst_zone="local";break;case 28:input.dst_zone="bad;summer";break;case 29:input.dst_zone="winter;summer";break;case 30:input.dst_zone="bad;";break;case 31:input.dst_zone.reset();break;case 32:input.dst_zone="null-zone;summer";break;case 33:input.dst_zone="throw-dst;summer";break;case 35:input.dst_zone=" summer ";break;case 38:input.library.reset();break;case 39:input.skeleton->clear();break;case 40:root->name="";input.skeleton->push_back(folder(3,"My Inventory"));input.skeleton->push_back(folder(4,"My Inventory"));break;case 41:root->name="Not Root";break;case 42:input.friends->push_back(buddy(std::string(32,'0')+"tail",2,3));break;case 44:root->name.reset();break;case 43:account.first_name.reset();account.last_name.reset();input.where.reset();input.message.reset();input.map_url.reset();input.profile_url.reset();input.openid_url.reset();input.search_url.reset();input.currency.reset();input.classified_fee.reset();input.destinations_url.reset();input.avatars_url.reset();break;}
 if((variant&2)&&input.skeleton&&!input.skeleton->empty()){input.skeleton->at(0)->version=0;input.skeleton->at(0)->type=13;} // only when a skeleton exists, below
 std::unique_ptr<LoginResponse> response;std::string status="OK",xml,llsd;
 try{response=std::make_unique<LoginResponse>(input,env,[&]{return id(++random);},[&]{++clocks;return 1700000000.;});}catch(...){status="EX";}
 if(response){xml=view(response->to_xml_rpc());llsd=view(response->to_llsd());}
 return "CON|"+status+"|"+std::to_string(random)+":"+std::to_string(clocks)+"|"+hex(events)+"|"+xml+"|"+llsd;
}
